usage:
import { Toaster, useToasts } from "@/components/design-for-ai/toast-stack";

// Once, near the root of your app:
<Toaster position="bottom-right" theme="dark" />

// Anywhere below it (the module also exports a `toast` object for use outside React):
function SaveButton() {
  const { promise } = useToasts();
  return (
    <button onClick={() => promise(save(), { loading: "Saving…", success: "Saved", error: "Couldn’t save" })}>
      Save
    </button>
  );
}
